    private void refreshNav(){nav.removeAll();for(String page:List.of("Genel Bakış","Ürünler","Malzemeler","Tedarikçi Fiyatları","Maliyet Hesapla","Teklifler","Raporlar","Excel Aktarımı","Ayarlar")){JButton b=new JButton(page);b.setHorizontalAlignment(SwingConstants.LEFT);b.setFont(Ui.font(13,activePage.equals(page)?Font.BOLD:Font.PLAIN));b.setBackground(activePage.equals(page)?Ui.BLUE_LIGHT:Ui.WHITE);b.setForeground(activePage.equals(page)?Ui.BLUE:Ui.INK);b.setBorder(BorderFactory.createEmptyBorder(12,15,12,8));b.setMaximumSize(new Dimension(208,44));b.setFocusPainted(false);b.addActionListener(e->showPage(page));nav.add(b);nav.add(Box.createVerticalStrut(3));}nav.revalidate();nav.repaint();}
    private void showPage(String page){try{activePage=page;refreshNav();title.setText(page);subtitle.setText(switch(page){case "Genel Bakış"->"Ürün, fiyat ve tekliflerinizin kısa özeti";case "Maliyet Hesapla"->"Canlı maliyet ve sipariş hesabı";case "Excel Aktarımı"->"Dosyaları inceleyin, sorunları görün, sonra kaydedin";default->"Biotex çalışma alanı";});body.removeAll();switch(page){case "Genel Bakış"->dashboard();case "Ürünler"->products();case "Malzemeler"->materials();case "Tedarikçi Fiyatları"->prices();case "Maliyet Hesapla"->cost();case "Teklifler"->estimates();case "Raporlar"->reports();case "Excel Aktarımı"->imports();case "Ayarlar"->settings();}body.revalidate();body.repaint();}catch(Exception e){error(e);}}
    private void error(Exception e){JOptionPane.showMessageDialog(this,e.getMessage()==null?e.toString():e.getMessage(),"İşlem yapılamadı",JOptionPane.ERROR_MESSAGE);}
