    private Map<String,String> form(String name,Field... fields){JPanel panel=new JPanel(new GridBagLayout());panel.setBackground(Ui.WHITE);GridBagConstraints g=new GridBagConstraints();g.anchor=GridBagConstraints.WEST;g.fill=GridBagConstraints.HORIZONTAL;g.insets=new Insets(7,8,7,8);Map<String,JComponent> controls=new LinkedHashMap<>();int i=0;for(Field field:fields){g.gridx=0;g.gridy=i;g.weightx=0;panel.add(Ui.label(field.label(),12,true),g);g.gridx=1;g.weightx=1;JComponent input;if(field.choices()!=null&&field.choices().length>0){JComboBox<String> c=new JComboBox<>(field.choices());c.setSelectedItem(field.value());input=c;}else input=Ui.field(field.value(),24);panel.add(input,g);controls.put(field.key(),input);i++;}int choice=JOptionPane.showConfirmDialog(this,panel,name,JOptionPane.OK_CANCEL_OPTION,JOptionPane.PLAIN_MESSAGE);if(choice!=JOptionPane.OK_OPTION)return null;Map<String,String> out=new LinkedHashMap<>();for(var e:controls.entrySet())out.put(e.getKey(),e.getValue() instanceof JTextField f?f.getText().trim():Objects.toString(((JComboBox<?>)e.getValue()).getSelectedItem(),""));return out;}
    private static Long optionalId(String text){return text==null||text.isBlank()?null:Long.parseLong(text);}
    private static String value(Map<String,String> m,String key){String v=m.get(key);return v==null||v.isBlank()?null:v;}
