    private void cost(){
        List<Map<String,Object>> products=service.rows("products");JComboBox<String> choice=new JComboBox<>();for(var p:products)choice.addItem(p.get("code")+"  ·  "+p.get("name"));if(selectedProduct>0)for(int i=0;i<products.size();i++)if(num(products.get(i).get("id"))==selectedProduct)choice.setSelectedIndex(i);
        JTextField quantity=Ui.field("1",10),date=Ui.field(LocalDate.now().toString(),12),customer=Ui.field("",10);
        JPanel inputs=Ui.card();inputs.setPreferredSize(new Dimension(270,0));JPanel fields=vertical();fields.add(Ui.label("Hesap girdileri",17,true));fields.add(Box.createVerticalStrut(18));for(Component[] pair:new Component[][]{{Ui.label("Ürün",12,true),choice},{Ui.label("Sipariş adedi",12,true),quantity},{Ui.label("Kur tarihi",12,true),date},{Ui.label("Müşteri ID",12,true),customer}}){fields.add(pair[0]);fields.add(Box.createVerticalStrut(5));pair[1].setMaximumSize(new Dimension(Integer.MAX_VALUE,38));fields.add(pair[1]);fields.add(Box.createVerticalStrut(16));}inputs.add(fields,BorderLayout.NORTH);
        JTextArea detail=new JTextArea();detail.setEditable(false);detail.setLineWrap(true);detail.setWrapStyleWord(true);detail.setFont(Ui.font(12,Font.PLAIN));detail.setForeground(Ui.INK);detail.setBackground(Ui.WHITE);detail.setMargin(new Insets(12,12,12,12));JPanel center=Ui.card();center.add(headingRow("Hesap ayrıntısı","Miktar, fiyat, kur ve katsayılar satır satır gösterilir.",Ui.button("Ürün detayını aç",false,()->safe(()->{selectedProduct=num(products.get(choice.getSelectedIndex()).get("id"));productDetail();}))),BorderLayout.NORTH);center.add(Ui.scroll(detail));
        JPanel summary=Ui.card();summary.setPreferredSize(new Dimension(300,0));JPanel summaryItems=vertical();summary.add(summaryItems,BorderLayout.NORTH);
        Runnable compute=()->safe(()->{if(choice.getSelectedIndex()<0)throw new IllegalArgumentException("Önce ürün oluşturun");selectedProduct=num(products.get(choice.getSelectedIndex()).get("id"));var e=service.calculate(selectedProduct,quantity.getText(),date.getText());showCostResult(e,detail,summaryItems);});
        JPanel actions=Ui.row(Ui.button("Hesapla",true,compute),Ui.button("Taslak kaydet",false,()->saveCost(products,choice,quantity,date,customer,false)),Ui.button("Onayla",false,()->saveCost(products,choice,quantity,date,customer,true)));center.add(actions,BorderLayout.SOUTH);
        JPanel work=new JPanel(new BorderLayout(14,14));work.setOpaque(false);work.add(inputs,BorderLayout.WEST);work.add(center,BorderLayout.CENTER);work.add(summary,BorderLayout.EAST);body.add(work,BorderLayout.CENTER);compute.run();
        Runnable relayout=()->{boolean compact=body.getWidth()<1080;work.remove(summary);summary.setPreferredSize(compact?new Dimension(0,250):new Dimension(300,0));work.add(summary,compact?BorderLayout.SOUTH:BorderLayout.EAST);work.revalidate();work.repaint();};
        work.addComponentListener(new ComponentAdapter(){public void componentResized(ComponentEvent e){relayout.run();}});SwingUtilities.invokeLater(relayout);
    }
    private String money(BigDecimal value,boolean sale){if(value==null)return "—";int digits=sale?2:4;java.text.NumberFormat f=java.text.NumberFormat.getNumberInstance(Locale.forLanguageTag("tr-TR"));f.setMinimumFractionDigits(digits);f.setMaximumFractionDigits(digits);f.setRoundingMode(RoundingMode.HALF_UP);return f.format(value)+" TRY";}
    private void showCostResult(CostEngine.Estimate e,JTextArea detail,JPanel summary){
        StringBuilder d=new StringBuilder();int i=1;
        for(var line:e.lines())d.append(i++).append(". ").append(line.detail()).append("\n   = ").append(line.cost()==null?"Hesaplanamadı":line.cost()+" TRY").append("\n\n");
        if(!e.issues().isEmpty())d.append("ONAY ENGELLERİ\n").append(String.join("\n",e.issues()));detail.setText(d.toString());
        summary.removeAll();summary.add(Ui.label("Maliyet özeti",17,true));summary.add(Box.createVerticalStrut(10));
        for(String[] item:new String[][]{{"Malzeme",money(e.material(),false)},{"İşçilik",money(e.labor(),false)},{"Ek gider",money(e.extras(),false)},{"Sipariş sabit gideri",money(e.orderFixed(),false)},{"Birim maliyet",money(e.unitCost(),false)},{"Satış fiyatı",money(e.unitPrice(),true)},{"Sipariş toplamı",money(e.orderTotal(),true)}}){
            JPanel r=new JPanel(new BorderLayout());r.setOpaque(false);r.add(Ui.label(item[0],12,false),BorderLayout.WEST);r.add(Ui.label(item[1],12,true),BorderLayout.EAST);summary.add(r);summary.add(Box.createVerticalStrut(6));
        }
        JLabel status=Ui.label(e.approvable()?"Hesap onaya hazır":"Eksik girişler var · taslak",12,true);status.setForeground(e.approvable()?Ui.BLUE:Ui.RED);summary.add(status);summary.revalidate();summary.repaint();
    }
    private void saveCost(List<Map<String,Object>> products,JComboBox<String> choice,JTextField quantity,JTextField date,JTextField customer,boolean approve){safe(()->{if(choice.getSelectedIndex()<0)throw new IllegalArgumentException("Önce ürün oluşturun");long product=num(products.get(choice.getSelectedIndex()).get("id"));long id=service.saveEstimate(product,quantity.getText(),date.getText(),customer.getText().isBlank()?0:Long.parseLong(customer.getText()),approve);message((approve?"Onaylı teklif":"Taslak")+" kaydedildi · #"+id);});}
