    private Path choose(String extension){JFileChooser chooser=new JFileChooser();chooser.setSelectedFile(new java.io.File("biotex-rapor."+extension));return chooser.showSaveDialog(this)==JFileChooser.APPROVE_OPTION?chooser.getSelectedFile().toPath():null;}
    private void reports(){JPanel card=Ui.card();JTable t=Ui.table(service.rows("estimates"),"id","productName","customerName","quantity","status","unitPrice","orderTotal");card.add(headingRow("Raporlar","Teklif PDF'si iç maliyeti göstermez.",Ui.button("Teklif PDF",true,()->exportEstimate(t,"OFFER_PDF")),Ui.button("Maliyet PDF",false,()->exportEstimate(t,"COST_PDF")),Ui.button("Maliyet XLSX",false,()->exportEstimate(t,"COST_XLSX")),Ui.button("İhtiyaç XLSX",false,()->exportDemand()),Ui.button("Karşılaştırma XLSX",false,()->exportComparison())),BorderLayout.NORTH);card.add(Ui.scroll(t));showCard(card);}
    private void exportEstimate(JTable t,String kind){safe(()->{var estimate=service.one("estimates",selectedId(t));boolean pdf=kind.endsWith("PDF");Path output=choose(pdf?"pdf":"xlsx");if(output==null)return;List<String> lines=new ArrayList<>();if(kind.equals("OFFER_PDF")){if(!"APPROVED".equals(estimate.get("status")))throw new IllegalArgumentException("Müşteri teklifi yalnız onaylı kayıttan alınır");lines.add("Müşteri: "+Objects.toString(estimate.get("customerName"),"—"));lines.add("Ürün: "+estimate.get("productName"));lines.add("Miktar: "+estimate.get("quantity"));lines.add("Tarih: "+estimate.get("createdAt"));lines.add("Para birimi: TRY");lines.add("Birim fiyat: "+estimate.get("unitPrice")+" TRY");lines.add("Toplam: "+estimate.get("orderTotal")+" TRY");}else{var snap=(Map<?,?>)estimate.get("snapshot");for(String key:List.of("materialCost","laborCost","extraCost","orderFixed","unitCost","unitPrice","orderTotal"))lines.add(Ui.header(key)+": "+snap.get(key)+" TRY");lines.add("Ürün: "+estimate.get("productName"));lines.add("Adet: "+estimate.get("quantity"));}if(pdf)Reports.pdf(output,kind.equals("OFFER_PDF")?"Biotex Teklif":"Biotex Maliyet Dökümü",lines,home.resolve("assets/biotex-logo.jpg"));else{List<String[]> rows=new ArrayList<>();for(String line:lines)rows.add(new String[]{line});Reports.xlsx(output,rows);}message("Rapor kaydedildi: "+output);});}
    private void exportDemand(){safe(()->{var f=form("Malzeme ihtiyacı",new Field("productId","Ürün ID",selectedProduct==0?"":selectedProduct),new Field("quantity","Sipariş adedi","1"));if(f==null)return;List<String[]> rows=new ArrayList<>();rows.add(new String[]{"Stok kodu","Malzeme","Birim","Sipariş ihtiyacı"});for(var d:service.demand(Long.parseLong(f.get("productId")),f.get("quantity")))rows.add(new String[]{d.code(),d.name(),d.unit(),d.quantity().toPlainString()});Path output=choose("xlsx");if(output!=null){Reports.xlsx(output,rows);message("Rapor kaydedildi: "+output);}});}
    private void exportComparison(){safe(()->{var f=form("Karşılaştırma",new Field("quantity","Sipariş adedi","1"),new Field("date","Kur tarihi",LocalDate.now().toString()));if(f==null)return;List<String[]> rows=new ArrayList<>();rows.add(new String[]{"Kod","Ürün","Birim maliyet TRY","Birim fiyat TRY","Durum"});for(var p:service.rows("products")){var e=service.calculate(num(p.get("id")),f.get("quantity"),f.get("date"));rows.add(new String[]{str(p.get("code")),str(p.get("name")),e.unitCost()==null?"":e.unitCost().toPlainString(),e.unitPrice()==null?"":e.unitPrice().toPlainString(),e.issues().isEmpty()?"Hesaplandı":String.join("; ",e.issues())});}Path output=choose("xlsx");if(output!=null){Reports.xlsx(output,rows);message("Karşılaştırma kaydedildi: "+output);}});}
    private void imports(){JPanel card=Ui.card();javax.swing.table.DefaultTableModel model=new javax.swing.table.DefaultTableModel(new String[]{"Seç","Ürün / dosya","Şablon","Satır","Sorun"},0){public Class<?> getColumnClass(int c){return c==0?Boolean.class:Object.class;}public boolean isCellEditable(int r,int c){return c==0;}};JTable t=new JTable(model);t.setRowHeight(36);t.setFont(Ui.font(12,Font.PLAIN));t.getTableHeader().setFont(Ui.font(12,Font.BOLD));JTextArea issues=new JTextArea();issues.setEditable(false);issues.setFont(Ui.font(12,Font.PLAIN));issues.setBackground(Ui.BG);issues.setMargin(new Insets(12,12,12,12));t.getSelectionModel().addListSelectionListener(e->{int row=t.getSelectedRow();if(row<0||row>=previews.size())return;StringBuilder b=new StringBuilder();for(var issue:previews.get(row).issues())b.append(issue.severity()).append("  ·  ").append(issue.message()).append("  ·  ").append(issue.sheet()).append(" ").append(issue.cell()).append("\n");issues.setText(b.length()==0?"Görünür sorun bulunmadı.":b.toString());});
        JLabel status=Ui.label("Kaynak dosyayı seçin; hiçbir kayıt önizleme sırasında değişmez.",12,false);
        card.add(headingRow("Excel aktarımı","ZIP veya XLSX önizleyin, dosyaları seçin, tek işlemde kaydedin.",Ui.button("Dosya seç",true,()->{JFileChooser chooser=new JFileChooser();if(chooser.showOpenDialog(this)!=JFileChooser.APPROVE_OPTION)return;Path source=chooser.getSelectedFile().toPath();status.setText("Dosya okunuyor: "+source.getFileName());new SwingWorker<List<Importer.Preview>,Void>(){protected List<Importer.Preview> doInBackground()throws Exception{return Importer.preview(source);}protected void done(){try{previews=get();model.setRowCount(0);Set<String> seen=new HashSet<>();for(var p:previews)model.addRow(new Object[]{seen.add(p.sha256()),p.productName(),p.template(),p.recipeRows(),p.issues().size()});status.setText(previews.size()+" çalışma kitabı bulundu. Aynı içerik bir kez seçildi.");}catch(Exception e){error(e);}}}.execute();}),Ui.button("Seçilenleri aktar",false,()->{List<Importer.Preview> selected=new ArrayList<>();for(int i=0;i<previews.size();i++)if(Boolean.TRUE.equals(model.getValueAt(i,0)))selected.add(previews.get(i));if(selected.isEmpty()){message("Aktarılacak dosya seçilmedi");return;}status.setText("Kayıtlar hazırlanıyor...");new SwingWorker<Integer,Void>(){protected Integer doInBackground()throws Exception{return Importer.commit(store,selected);}protected void done(){try{int count=get();status.setText(count+" farklı dosya kaydedildi. Sorunlar JSON kaydında tutuldu.");message(count+" dosya aktarıldı");}catch(Exception e){error(e);}}}.execute();})),BorderLayout.NORTH);
        JSplitPane split=new JSplitPane(JSplitPane.VERTICAL_SPLIT,Ui.scroll(t),Ui.scroll(issues));split.setResizeWeight(.72);split.setBorder(BorderFactory.createEmptyBorder());card.add(split,BorderLayout.CENTER);card.add(status,BorderLayout.SOUTH);showCard(card);
    }
